package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import static org.junit.jupiter.api.Assertions.*;

class JdbcPointExchangeCouponTest extends JdbcCouponTransactionsTest {
 PointLedger points;PointExchanges exchanges;PointExchangeCatalog catalog;OperatorActor operator;
 @BeforeEach void pointCompatibility(){for(String t:List.of("point_exchange_record","point_exchange_catalog","point_checkin_request","point_verified_entry","point_verified_account","point_task_event","point_task_policy"))jdbc.update("DELETE FROM "+t);jdbc.update("INSERT INTO operator_account(id,account,password_hash,phone,can_points,can_coupon) VALUES(1,'point-exchange','unused','13800000000',1,1)");operator=new OperatorActor(1,session(1,"operator_account","OPERATOR",OperatorActor.APP,null),Instant.now().plusSeconds(3600));var identity=new OperatorIdentity(jdbc,null,new DataSourceTransactionManager(jdbc.getDataSource()));var policies=new PointTaskPolicies(db,identity);points=new PointLedger(db,policies,"test-app",true,true);catalog=new PointExchangeCatalog(db,inventory,identity);exchanges=new PointExchanges(db,catalog,inventory,points,true);jdbc.update("UPDATE auth_session SET point_identity_source='VERIFIED_WECHAT' WHERE id=?",owner.session());}
 long exchangedCoupon(String kind){long publicCoupon=issue(owner,kind,kind.equals("SERVICE")?"0.00":"5.00",kind.equals("SERVICE")?"0.00":"10.00",3600);long c=jdbc.queryForObject("SELECT coupon_id FROM user_coupon WHERE id=?",Long.class,publicCoupon);inventory.pool(operator,c,key(),json.createObjectNode().put("selected",true).put("expected_pool_revision",0));var b=json.createObjectNode().put("coupon_id",c).put("publication_revision",2).put("pool_revision",1).put("points_cost",5).put("per_owner_limit",2).put("source_note","合成使用兼容测试").put("valid_from",clock.value.toString()).put("valid_to",clock.value.plusSeconds(3600).toString());long p=catalog.create(operator,key(),b).path("data").path("id").asLong();catalog.status(operator,p,key(),json.createObjectNode().put("expected_revision",1).put("status","PUBLISHED"));var policies=new PointTaskPolicies(db,new OperatorIdentity(jdbc,null,new DataSourceTransactionManager(jdbc.getDataSource())));var task=json.createObjectNode().put("task_type","CHECK_IN").put("points",7).put("source_note","合成签到测试").put("valid_from",clock.value.toString()).put("valid_to",clock.value.plusSeconds(86400).toString());long taskId=policies.create(operator,key(),task).path("data").path("id").asLong();policies.status(operator,taskId,key(),json.createObjectNode().put("expected_revision",1).put("status","PUBLISHED"));var e=points.checkin(owner,key(),json.createObjectNode().put("day",clock.value.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate().toString()).put("policy_id",taskId).put("policy_revision",2));assertTrue(points.credit(e.path("data").path("event_id").asLong()));return exchanges.exchange(owner,key(),json.createObjectNode().put("catalog_id",p).put("catalog_revision",2)).path("data").path("user_coupon_id").asLong();}
 @Test void pointsServiceVoucherUsesIndependentReceiptWithoutPaymentOrCommission(){long uc=exchangedCoupon("SERVICE");service.redeem(shop,key(),redeemBody(authorize(uc,0)));assertEquals("USED",couponState(uc));assertEquals(1,count("coupon_service_redemption"));assertEquals(0,count("payment"));assertEquals(0,count("order"));assertEquals(0,count("merchant_commission_entry"));assertEquals(2L,points.overview(owner).get("balance"));assertEquals(1,count("point_exchange_record"));}
 @Test void pointsAmountCouponKeepsCashCommissionAndFullRefundReturnsSameCouponWithoutPoints(){policy(false);long uc=exchangedCoupon("DISCOUNT"),o=paid(uc);assertEquals("7.34",orders.detail(owner,o).get("amount_due"));assertEquals(new java.math.BigDecimal("7.34"),jdbc.queryForObject("SELECT base_amount FROM order_commission_snapshot WHERE order_id=?",java.math.BigDecimal.class,o));long r=request(o);approve(o);refundWorker(q->new RefundChannel.Result(true,refundNotice(r,key(),"SUCCEEDED"))).sweep();assertEquals("AVAILABLE",couponState(uc));assertEquals("RETURNED",allocation(o));assertEquals(2L,points.overview(owner).get("balance"));assertEquals(2,count("point_verified_entry"));assertEquals(1,count("point_exchange_record"));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM coupon_issue WHERE origin='POINTS'",Integer.class));}
 @Test void pointsRefundAfterCouponDeadlineDoesNotExtendCouponOrReturnPoints(){long uc=exchangedCoupon("DISCOUNT"),o=paid(uc),r=request(o);approve(o);var original=jdbc.queryForObject("SELECT terms_json FROM coupon_publication WHERE coupon_id=(SELECT coupon_id FROM user_coupon WHERE id=?)",String.class,uc);clock.value=clock.value.plusSeconds(3601);refundWorker(q->new RefundChannel.Result(true,refundNotice(r,key(),"SUCCEEDED"))).sweep();assertEquals("RETURNED",allocation(o));assertEquals("AVAILABLE",couponState(uc));var mine=(List<?>)inventory.mine(owner,1,20).get("items");var returned=mine.stream().map(v->(Map<?,?>)v).filter(v->((Number)v.get("user_coupon_id")).longValue()==uc).findFirst().orElseThrow();assertEquals("EXPIRED",returned.get("availability"));assertEquals(original,jdbc.queryForObject("SELECT terms_json FROM coupon_publication WHERE coupon_id=(SELECT coupon_id FROM user_coupon WHERE id=?)",String.class,uc));assertEquals(2L,points.overview(owner).get("balance"));}
}
